from playwright.sync_api import sync_playwright
OUT='/tmp/claude-0/-home-claude/48154143-1c92-5c72-a63a-d8264194645f/scratchpad/e2e/'
ok=lambda c,m: print(('  ok  ' if c else '  FAIL ')+m)
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_context(viewport={'width':1400,'height':950}, accept_downloads=True, service_workers='block').new_page()
    errs=[]; pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('console', lambda m: errs.append(m.text) if m.type=='error' and 'TUNNEL' not in m.text and 'Failed to load' not in m.text else None)
    pg.goto('http://localhost:8765/index.html'); pg.wait_for_timeout(500); pg.evaluate("document.getElementById('config').open=false")
    pg.click('#nav button[data-view="exp"]'); pg.set_input_files('#xFile','test/exp/stocklist_miami.xlsx'); pg.wait_for_timeout(1200)
    ok('Pedido de exportação' in pg.inner_text('#vExp') and 'Roteiro' in pg.inner_text('#vExp'),'abas Pedido de exportação | Roteiro dentro da Exportação')
    pg.click('#xNum summary'); pg.wait_for_timeout(100); ok(pg.locator('#xLast').is_visible(),'numeração recolhível')
    for k,v in {'ex.nf':'1','ex.dued':'1','ex.mawb':'1','ex.dep':'2026-11-06T22:30','ex.gta':'1','ex.lpcoMapa':'E1','ex.lpcoIbama':'E2'}.items(): pg.fill(f'[data-xp="{k}"]',v)
    with pg.expect_download() as d: pg.click('[data-xa="zip"]')
    pg.wait_for_timeout(300)
    pg.click('[data-xa="vrot"]'); pg.wait_for_timeout(200); ok('ROTEIRO DE REVISÃO' in pg.inner_text('#vExp'),'roteiro abre dentro da exportação')
    pg.click('[data-xst="inv:o"]'); ok('1 OK' in pg.inner_text('#vExp'),'marcar OK')
    pg.screenshot(path=OUT+'r1.png')
    pg.click('[data-xrotgo="cz"]'); pg.wait_for_timeout(300); ok(pg.locator('#xModal').count()==1,'↗ abre prévia do CZI'); pg.keyboard.press('Escape')
    ok('Pedido de exportação' in pg.inner_text('#vExp') and pg.locator('#xFile').count()==1,'voltou ao pedido')
    pg.click('#nav button[data-view="hist"]'); pg.wait_for_timeout(300)
    t=pg.inner_text('#vHist'); ok('Exportações' in t and '018/2026' in t and 'Miami' in t,'Histórico mostra a exportação 018/2026')
    pg.screenshot(path=OUT+'r2.png',full_page=True)
    pg.click('[data-htipo="nac"]'); ok('018/2026' not in pg.inner_text('#vHist'),'filtro Nacionais esconde exportações')
    pg.click('[data-htipo="exp"]'); ok('018/2026' in pg.inner_text('#vHist') and 'Histórico de pedidos' not in pg.inner_text('#vHist'),'filtro Exportações mostra só exportações')
    pg.click('[data-xopen]'); pg.wait_for_timeout(300); ok(pg.evaluate("PP.S.view")=='exp' and '018/2026' in pg.inner_text('.xbig'),'Abrir leva à Exportação com a 018')
    pg.click('#nav button[data-view="hist"]'); pg.click('[data-htipo="exp"]')
    pg.once('dialog', lambda d: d.accept()); pg.click('[data-xdelh]'); pg.wait_for_timeout(300); ok('Nenhuma exportação salva' in pg.inner_text('#vHist'),'excluir remove do histórico')
    ok(pg.evaluate("PP.exp.cfg().last")==18,'número continua usado (018)')
    print('errs',errs)
